from decimal import Decimal
from ledgerly.adjustments import goodwill_credit
from ledgerly.models import Invoice, LineItem
from ledgerly.errors import BillingError
from ledgerly import audit

def inv(status="issued", total="50.00"):
    return Invoice("inv_1","cus_1",lines=[LineItem("Seat",1,Decimal(total))],status=status)

# basic
r = goodwill_credit(inv(), Decimal("5.00"), "late")
print(r, type(r["amount"]))
# non-positive
for a in ["0.00","-1.00"]:
    try: goodwill_credit(inv(), a, "x")
    except BillingError as e: print("nonpos", e.code)
# exceeds total
try: goodwill_credit(inv(), "50.01", "x")
except BillingError as e: print("exceeds", e.code)
# not issued
try: goodwill_credit(inv("draft"), "5.00", "x")
except BillingError as e: print("state", e.code)
# approval threshold
try: goodwill_credit(inv(total="2000.00"), "1000.01", "x")
except BillingError as e: print("approval", e.code)
print(goodwill_credit(inv(total="2000.00"), "1000.00", "x")["amount"])
print(goodwill_credit(inv(total="2000.00"), "1000.01", "x", approved_by="mgr")["amount"])
# idempotency
audit.clear()
a = goodwill_credit(inv(), "5.00", "x", idempotency_key="k1")
b = goodwill_credit(inv(), "5.00", "x", idempotency_key="k1")
print(a==b, len(audit.events("goodwill_credit")))
